'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const I=require('./index.cjs'),S=require('./cleanup-schema.cjs'),B=require('./cleanup-backend.cjs'),F=require('./fixtures.cjs'),X=require('./fence-fixtures.cjs');
const root=process.env.PUBLIC_TEST_TMP_ROOT,python=process.env.PUBLIC_TEST_PYTHON;assert(root&&python);
async function control(loss){const dir=fs.mkdtempSync(path.join(root,'unused-pipe-')),f=X.fixture(dir),env={...F.env(f.c),PUBLIC_EFFECT_MARKER:path.join(dir,'public-effect-marker')};for(const k of ['PATH','HOME','TMPDIR'])if(process.env[k])env[k]=process.env[k];let starts=0;const commands=[],phases=[];
 const worker=async pack=>{const {request:q,context:c,bundle,current_records:held}=pack;commands.push(q.command);if(q.command==='READ_TARGET')return B.readTarget(c,f.deps);if(q.command==='HISTORY')return B.handlerHistory(c,bundle,held,f.deps);phases.push(q.payload.phase);const value=await B.persist(q.payload,c,bundle,held,f.deps);if(q.payload.phase===loss)throw new Error('PUBLIC_ACK_LOSS');return value;};
 const spawnChild=(exe,args,options)=>{starts++;assert.deepEqual(args,['-I','-m','just_akash.scanner_v2_unused_cleanup']);const source=path.resolve(__dirname,'../../..'),fixture=path.join(source,'tests/fixtures/unused_pipe_child.py');return spawn(exe,['-I','-c',`import sys,runpy;sys.path.insert(0,${JSON.stringify(source)});runpy.run_path(${JSON.stringify(fixture)},run_name='__main__')`],options);};let value=null;try{value=await I.supervise({python,env,worker,spawnChild});}catch{}return{value,starts,commands,phases,marker:env.PUBLIC_EFFECT_MARKER};}
test('actual immutable reader and Node supervisor feed real Python pipe and exact-ID one-use removal',async()=>{const x=await control();assert(x.value);assert.equal(x.starts,1);assert.deepEqual(x.phases,['NO_WIRE','UNKNOWN','ACK']);assert.equal(fs.readFileSync(x.marker,'utf8'),'991');assert(x.commands.includes('READ_TARGET')&&x.commands.filter(v=>v==='HISTORY').length>=2);});
test('lost UNKNOWN readback cannot reach the actual removal boundary or start another child',async()=>{const x=await control('UNKNOWN');assert.equal(x.value,null);assert.equal(x.starts,1);assert.deepEqual(x.phases,['NO_WIRE','UNKNOWN']);assert(!fs.existsSync(x.marker));});
test('lost ACK after one removal keeps UNKNOWN and never replays the effect or child',async()=>{const x=await control('ACK');assert.equal(x.value,null);assert.equal(x.starts,1);assert.equal(x.phases.filter(p=>p==='UNKNOWN').length,1);assert.equal(fs.readFileSync(x.marker,'utf8'),'991');});
